// Question → vecteur mots-clés (le vecteur sémantique est calculé par Ollama juste après).
const question = String($json.chatInput ?? '').trim();
if (!question) throw new Error('Question vide.');
return [{ json: { question, mots: vecteurMots(question, true) } }];

// Passages candidats issus de la recherche hybride, numérotés.
const pts = $json.result?.points ?? [];
return [{ json: { question: $('Préparer la recherche').first().json.question, candidats: pts.map((p, i) => ({ n: i + 1, source: p.payload.source, section: p.payload.section, page: p.payload.page, texte: p.payload.texte, score_rrf: Math.round(p.score * 1000) / 1000 })) } }];

// Garde les passages jugés pertinents (2 ou 3 sur 3), 4 au plus, dans l'ordre de pertinence.
const c = $('Passages candidats').first().json;
const notes = new Map(($json.output?.notes ?? []).map(x => [Number(x.n), Number(x.pertinence)]));
const gardes = c.candidats.map(p => ({ ...p, pertinence: notes.get(p.n) ?? 0 })).filter(p => p.pertinence >= 2)
  .sort((a, b) => b.pertinence - a.pertinence || a.n - b.n).slice(0, 4).map((p, i) => ({ ...p, ref: i + 1 }));
return [{ json: { question: c.question, sources: gardes, nb: gardes.length } }];

// Vérifie les citations : seules les références [n] fournies sont gardées ; liste des sources citées en fin de réponse.
const { sources } = $('Garder les meilleurs passages').first().json;
let rep = String($json.text ?? '').trim();
const valides = new Set(sources.map(s => s.ref));
rep = rep.replace(/\[(\d+)\]/g, (m, n) => valides.has(+n) ? m : '');
const citees = [...new Set([...rep.matchAll(/\[(\d+)\]/g)].map(m => +m[1]))].sort((a, b) => a - b);
const lignes = citees.map(n => { const s = sources.find(x => x.ref === n); return `- [${n}] ${s.source} · ${s.section}${s.page ? ' · p. ' + s.page : ''}`; });
const pied = lignes.length ? '\n\n**Sources**\n\n' + lignes.join('\n') : '\n\n⚠ Réponse sans source citée : à vérifier.';
return [{ json: { output: rep + pied, citations: citees.length } }];
